            if (ok) {
                for (zmaster587.advancedRocketry.entity.EntityDummy d : riders) {
                    d.setPositionAndUpdate(d.posX + (dstX - sx), d.posY + (dstY - sy), d.posZ + (dstZ - sz));
                }
            }
