            info.put("fuel", fuel);
            info.put("thrust", rocket.stats.getThrust());
            info.put("weight_no_fuel", rocket.stats.getWeight_NoFuel());
            info.put("breakingProb", rocket.storage.getBreakingProbability());
            // expose stats fields that aggregate per-block
