                    java.lang.reflect.Field ctf = zmaster587.advancedRocketry.satellite.SatelliteData
                            .class.getDeclaredField("collectionTime");
                    ctf.setAccessible(true);
                    int collectionTime = (int) (200.0 / Math.sqrt(0.1 * powerGen));
